// Import the Discord.js library
const { Client, GatewayIntentBits, SlashCommandBuilder } = require('discord.js');

// Create a new Discord client
const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent
  ]
});

// Define the ban command
const banCommand = new SlashCommandBuilder()
  .setName('ban')
  .setDescription('Bans a user from the server')
  .addUserOption(option => option.setName('user').setDescription('The user to ban').setRequired(true))
  .addStringOption(option => option.setName('reason').setDescription('The reason for the ban').setRequired(true));

// Register the ban command
client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  const { commandName, options } = interaction;

  if (commandName === 'ban') {
    const user = options.getUser('user');
    const reason = options.getString('reason');

    // Ban the user
    await interaction.guild.members.ban(user, { reason });

    // Send a message to the user
    await interaction.reply(`You have been banned from the server for ${reason}.`);
  }
});

// Login to the Discord API
client.login('YOUR_TOKEN_HERE');
```

